import os
from pptx import Presentation
from pptx.util import Inches, Cm, Pt
from pptx.enum.text import PP_ALIGN
from pptx.dml.color import RGBColor
from PIL import Image
os.makedirs(os.path.dirname(p), exist_ok=True)
prs = Presentation()
blank = prs.slide_layouts[6]
title_layout = prs.slide_layouts[0]
def add_blank():
    return prs.slides.add_slide(blank)
def add_title(text='Title'):
    s = prs.slides.add_slide(title_layout)
    s.shapes.title.text = text
    return s
def set_bg(slide, rgb):
    fill = slide.background.fill
    fill.solid()
    fill.fore_color.rgb = RGBColor(*rgb)
if kind == 'image_2cm_slide2':
    add_blank(); s = add_blank()
    img = '/tmp/oracle_seed_image.png'
    Image.new('RGB', (100,100), (80,140,200)).save(img)
    s.shapes.add_picture(img, Inches(1), Inches(1), width=Cm(2), height=Cm(2))
elif kind == 'bg_all':
    for _ in range(3):
        s = add_blank(); set_bg(s, tuple(kw['rgb']))
elif kind == 'bg_first':
    s = add_blank(); set_bg(s, tuple(kw['rgb']))
elif kind == 'text_align':
    s = add_blank()
    aligns = [PP_ALIGN.LEFT, PP_ALIGN.CENTER, PP_ALIGN.RIGHT]
    for i,a in enumerate(aligns):
        box = s.shapes.add_textbox(Inches(1), Inches(1+i), Inches(4), Inches(.5))
        para = box.text_frame.paragraphs[0]; para.alignment = a; para.text = 'Text %d' % i
elif kind == 'title':
    idx = kw.get('slide_index', 0)
    for i in range(idx+1):
        s = add_title(kw['text'] if i == idx else 'Title')
elif kind == 'title_font_size':
    idx = kw.get('slide_index', 0)
    for i in range(idx+1):
        s = add_title('Product Comparison' if i == idx else 'Title')
    for para in s.shapes.title.text_frame.paragraphs:
        for run in para.runs:
            run.font.size = Pt(kw['size'])
elif kind == 'table':
    for _ in range(kw.get('slide_index',0)+1):
        s = add_blank()
    tbl = s.shapes.add_table(kw['rows'], kw['cols'], Inches(1), Inches(1), Inches(5), Inches(2)).table
    for r in range(kw['rows']):
        for c in range(kw['cols']):
            tbl.cell(r,c).text = kw.get('cells', {}).get((r,c), 'R%dC%d' % (r,c))
elif kind == 'notes':
    s = add_title('Title')
    s.notes_slide.notes_text_frame.text = kw['notes']
elif kind == 'font_sizes':
    s = add_blank()
    for i,sz in enumerate(kw['sizes']):
        box = s.shapes.add_textbox(Inches(1), Inches(1+i), Inches(4), Inches(.5))
        para = box.text_frame.paragraphs[0]
        run = para.add_run(); run.text = 'Text %d' % i; run.font.size = Pt(sz)
elif kind == 'slide_text':
    for _ in range(kw.get('slide_index',0)+1):
        s = add_blank()
    box = s.shapes.add_textbox(Inches(1), Inches(1), Inches(5), Inches(1))
    run = box.text_frame.paragraphs[0].add_run(); run.text = kw['text']
    if kw.get('size'): run.font.size = Pt(kw['size'])
elif kind == 'four_images':
    img = '/tmp/oracle_seed_image.png'; Image.new('RGB',(100,100),(120,90,30)).save(img)
    for _ in range(4):
        s = add_blank(); s.shapes.add_picture(img, Inches(1), Inches(1), width=Inches(2), height=Inches(2))
elif kind == 'note_bg':
    s = add_title(kw.get('title','Title')); set_bg(s, tuple(kw['rgb'])); s.notes_slide.notes_text_frame.text = kw['notes']
elif kind == 'fonts_all':
    for _ in range(3):
        s = add_title('Title')
        for shape in s.shapes:
            if getattr(shape, 'has_text_frame', False):
                shape.text_frame.text = 'DejaVu Sans text'
                for para in shape.text_frame.paragraphs:
                    for run in para.runs: run.font.name = kw['font']
prs.save(p)
